import { DarkTheme, NavigationContainer } from '@react-navigation/native';
import { createNativeStackNavigator } from '@react-navigation/native-stack';
import { Pressable, Text } from 'react-native';
import { ChatListScreen } from '../screens/ChatListScreen';
import { ChatScreen } from '../screens/ChatScreen';
import { LoginScreen } from '../screens/LoginScreen';
import { NewChatScreen } from '../screens/NewChatScreen';
import { RegisterScreen } from '../screens/RegisterScreen';
import { useAuth } from '../session/AuthContext';
import { theme } from '../theme';
import type { RootStackParamList } from './types';

const Stack = createNativeStackNavigator<RootStackParamList>();

const navigationTheme = {
  ...DarkTheme,
  colors: {
    ...DarkTheme.colors,
    primary: theme.colors.accent,
    background: theme.colors.bg,
    card: theme.colors.bar,
    text: theme.colors.text,
    border: theme.colors.hairline,
    notification: theme.colors.unread,
  },
};

export function RootNavigator() {
  const { user } = useAuth();

  return (
    <NavigationContainer theme={navigationTheme}>
      <Stack.Navigator
        screenOptions={{
          contentStyle: { backgroundColor: theme.colors.bg },
          headerStyle: { backgroundColor: theme.colors.bar },
          headerTintColor: theme.colors.text,
          headerTitleStyle: theme.typography.title,
        }}
      >
        {!user ? (
          <Stack.Group screenOptions={{ headerShown: false }}>
            <Stack.Screen name="Login" component={LoginScreen} />
            <Stack.Screen name="Register" component={RegisterScreen} />
          </Stack.Group>
        ) : (
          <>
            <Stack.Screen
              name="ChatList"
              component={ChatListScreen}
              options={({ navigation }) => ({
                title: 'Чаты',
                headerBackVisible: false,
                headerRight: () => (
                  <Pressable
                    accessibilityLabel="Новый чат"
                    accessibilityRole="button"
                    hitSlop={8}
                    onPress={() => navigation.navigate('NewChat')}
                  >
                    <Text style={{ color: theme.colors.accent, fontSize: 28 }}>+</Text>
                  </Pressable>
                ),
              })}
            />
            <Stack.Screen
              name="NewChat"
              component={NewChatScreen}
              options={{ title: 'Новый чат' }}
            />
            <Stack.Screen
              name="Chat"
              component={ChatScreen}
              options={({ route }) => ({ title: route.params.title })}
            />
          </>
        )}
      </Stack.Navigator>
    </NavigationContainer>
  );
}
